'use strict';

/**
* Trains a linear model via stochastic gradient descent.
*
* @module @stdlib/ml/strided/dsgd-trainer
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Params = require( '@stdlib/ml/base/sgd/params/float64' );
* var dsgdTrainer = require( '@stdlib/ml/strided/dsgd-trainer' );
* var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
*
* var M = 50;
* var N = 5;
* var lambda = 2.5;
* var eta0 = 0.01;
*
* var params = new Params({
*    'penaltyParams': new Float64Array( [ lambda, 0.0 ] ),
*    'learningRateParams': new Float64Array( [ eta0, 0.0 ] ),
*    'intercept': 0.0,
*    'maxIter': 500,
*    'penalty': 'l2',
*    'learningRate': 'constant',
*    'lossFunction': 'hinge',
*    'fitIntercept': true
* });
*
* var y = discreteUniform( M, 0.0, 30.0 );
* var X = discreteUniform( M*N, -5.0, 5.0 );
* var w = discreteUniform( N, -0.05, 0.05 );
* var workspace = new Float64Array( N );
*
* var out = dsgdTrainer( 'row-major', M, N, X, N, y, 1, w, 1, workspace, 1, params );
* returns <Float64Array>
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Params = require( '@stdlib/ml/base/sgd/params/float64' );
* var dsgdTrainer = require( '@stdlib/ml/strided/dsgd-trainer' );
* var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
*
* var M = 50;
* var N = 5;
* var lambda = 2.5;
* var eta0 = 0.01;
*
* var params = new Params({
*    'penaltyParams': new Float64Array( [ lambda, 0.0 ] ),
*    'learningRateParams': new Float64Array( [ eta0, 0.0 ] ),
*    'intercept': 0.0,
*    'maxIter': 500,
*    'penalty': 'l2',
*    'learningRate': 'constant',
*    'lossFunction': 'hinge',
*    'fitIntercept': true
* });
*
* var y = discreteUniform( M, 0.0, 30.0 );
* var X = discreteUniform( M*N, -5.0, 5.0 );
* var w = discreteUniform( N, -0.05, 0.05 );
* var workspace = new Float64Array( N );
*
* var out = dsgdTrainer.ndarray( M, N, X, N, 1, 0, y, 1, 0, w, 1, 0, workspace, 1, 0, params );
* returns <Float64Array>
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dsgdTrainer;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dsgdTrainer = main;
} else {
	dsgdTrainer = tmp;
}


// EXPORTS //

module.exports = dsgdTrainer;

// exports: { "ndarray": "dsgdTrainer.ndarray" }
